"""Compact chat captions; exact labels remain available in the message."""

CAPTIONS = {'S03': {'c1': 'Я основной ухаживающий', 'c2': 'Ухаживаем вместе', 'c3': 'Почти не участвую в уходе'}, 'Q01': {'c2': '1–3 года включительно', 'c3': '4–7 лет включительно', 'c4': '8–10 лет включительно'}, 'Q03': {'c2': 'От 3 до менее 12 месяцев'}, 'Q04': {'c1': 'Рекомендация ещё действует', 'c2': 'Наблюдение больше не нужно', 'c4': 'К ветеринару не обращались'}, 'Q34': {'c1': 'По рекомендации ветеринара', 'c2': 'Подобрать прогулки/нагрузку', 'c3': 'Разобраться в поведении', 'c4': 'Что было в моё отсутствие'}, 'Q09': {'c2': '8–30 дней назад', 'c3': '31–90 дней назад', 'c4': 'До 90 дней, точнее не помню', 'c5': 'Оказалось, раньше 90 дней'}, 'Q11': {'c1': 'Обычно ли это для собаки', 'c2': 'Нужен ли ветеринар', 'c3': 'Менять ли прогулки/нагрузку', 'c4': 'Менять ли кормление/питьё', 'c5': 'Как собака восстанавливается', 'c6': 'Что было в моё отсутствие'}, 'Q12': {'c1': 'Наблюдал без записей', 'c3': 'Запись или трансляция камеры', 'c4': 'Обсудил с близкими', 'c5': 'Искал в сети/сообществе', 'c6': 'Обратился к ветврачу/клинике', 'c7': 'Менял прогулки/режим/уход'}, 'Q13': {'c1': 'Не тратил время', 'c4': 'От 1 до менее 3 часов'}, 'Q15': {'c1': 'Стало ясно, решение принято', 'c2': 'Яснее, но вопросы остались', 'c3': 'Вопрос всё ещё неясен', 'c4': 'Ситуация развивается'}, 'Q16': {'c1': 'Дома, на прогулках и ночью', 'c2': 'Дома/на прогулках, ночью нет', 'c3': 'Только на прогулках/вне дома', 'c4': 'В эти сутки не надевали'}, 'Q27a': {'c1': 'Участвовал в предзаказе', 'c2': 'Заказал другой, без меня'}, 'Q32': {'c2': 'Не хочу оставлять контакт'}}

def caption(qid,option):
    return CAPTIONS.get(qid,{}).get(option['code'],option['label'].rstrip('.'))


def needs_details(qid,options):
    return any(caption(qid,o)!=o['label'].rstrip('.') for o in options)
